/* ===== redesign.js ===== */
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const skillsList=[['Acrobacias','dex'],['Arcanos','int'],['Atletismo','str'],['Engaño','cha'],['Historia','int'],['Interpretación','cha'],['Intimidación','cha'],['Investigación','int'],['Juego de manos','dex'],['Medicina','wis'],['Naturaleza','int'],['Percepción','wis'],['Perspicacia','wis'],['Persuasión','cha'],['Religión','int'],['Sigilo','dex'],['Supervivencia','wis'],['Trato con animales','wis']];
let currentView='profile',spellView='known',compView='active';
const sign=n=>n>=0?'+'+n:n;
function toast(t){document.querySelector('.toast')?.remove();let x=document.createElement('div');x.className='toast';x.textContent=t;document.body.append(x);setTimeout(()=>x.remove(),4500)}
function profile(){return character.combat_state.profile ||= {background:'Marinero',languages:'',senses:'',tools:'',notes:'',skills:{},saves:{wis:true,cha:true},conditions:[],initiativeBonus:0};}
function persist(){saveLocalBackup();setSyncBadge('Guardado en este dispositivo',true)}
function updateProfile(key,v){profile()[key]=v;persist();renderSupplement()}
function updateSkill(name,v){profile().skills[name]=Number(v);persist();renderSupplement()}
function updateSave(key,v){profile().saves[key]=v;persist();renderSupplement()}
const oldRenderAll=renderAll;
renderAll=function(){ensureProgressionData();oldRenderAll();if(document.getElementById('sidebar'))renderSupplement()};
const oldSaveCore=saveCharacterCore;
saveCharacterCore=async function(){await oldSaveCore();if(document.getElementById('sidebar'))renderSupplement()};
function renderSupplement(){const p=profile(),prof=2+Math.floor((character.level-1)/4);document.getElementById('sideLevel').textContent=character.class_name+' · Nivel '+character.level;document.getElementById('profileName').textContent=character.name;document.getElementById('heroClass').textContent=character.race+' · '+character.class_name;document.getElementById('heroLevel').textContent='Nivel '+character.level;document.getElementById('metricInit').textContent=sign(getMod(character.dex)+Number(p.initiativeBonus||0));document.getElementById('metricSpeed').textContent=character.speed+' pies';document.getElementById('acDisplay').title=calculateDynamicAC().breakdown;
 document.getElementById('skillsList').innerHTML=skillsList.map(([name,key])=>`<div class="skill-row"><span>${name} <small class="muted">${key.toUpperCase()}</small></span><span><select aria-label="Competencia en ${name}" onchange="updateSkill('${name}',this.value)">${[[0,'Sin competencia'],[1,'Competente'],[2,'Pericia']].map(([n,s])=>`<option value="${n}" ${Number(p.skills[name]||0)===n?'selected':''}>${s}</option>`).join('')}</select> <strong style="display:inline-block;width:35px;text-align:right">${sign(getMod(character[key])+Number(p.skills[name]||0)*prof)}</strong></span></div>`).join('');
 document.getElementById('savesList').innerHTML=['str','dex','con','int','wis','cha'].map(key=>`<div class="skill-row"><label><input type="checkbox" ${p.saves[key]?'checked':''} onchange="updateSave('${key}',this.checked)"> ${({str:'Fuerza',dex:'Destreza',con:'Constitución',int:'Inteligencia',wis:'Sabiduría',cha:'Carisma'})[key]}</label><strong>${sign(getMod(character[key])+(p.saves[key]?prof:0))}</strong></div>`).join('');
 document.getElementById('progressSummary').innerHTML=`<span class="eyebrow">Estado actual</span><h2 style="margin:8px 0">${esc(character.class_name)} · ${character.level}</h2><p>${character.hp_max} PG máximos · Competencia ${sign(prof)}</p><p>Invocaciones: ${esc((character.combat_state.invocations_known||[]).map(id=>ELDRITCH_INVOCATIONS_CATALOG.find(i=>i.id===id)?.name||id).join(' · '))}</p><p class="muted">Base de progresión: 5e (2014). Los elementos personalizados conservan las notas de tu mesa.</p>`;
 document.getElementById('levelHistory').innerHTML=(character.combat_state.level_history||[]).slice().reverse().map(x=>`<div class="history-item"><strong>Nivel ${x.from} → ${x.to}</strong><p>${esc(x.class)} · ${x.hp} PG obtenidos</p><small class="muted">${esc(x.date)}</small></div>`).join('')||'<p class="muted">Las próximas subidas quedarán registradas aquí.</p>';
 document.getElementById('conditionChips').innerHTML=['Agarrado','Asustado','Aturdido','Cegado','Derribado','Envenenado','Hechizado','Incapacitado','Inconsciente','Invisible','Paralizado','Petrificado','Restringido','Sordo'].map(c=>`<button class="tag" style="${p.conditions.includes(c)?'background:#5c4330;color:#fff':''}" onclick="toggleCondition('${c}')">${c}</button>`).join('');
 document.getElementById('passivePerception').textContent=10+getMod(character.wis)+Number(p.skills.Percepción||0)*prof;
}
function toggleCondition(c){let a=profile().conditions;a.includes(c)?a.splice(a.indexOf(c),1):a.push(c);persist();renderSupplement()}
switchTab=function(t){currentView=t;['profile','combat','equipment','spells','companions','progression'].forEach(v=>{document.getElementById('tab-'+v).classList.toggle('hidden',v!==t);document.querySelector('[data-view="'+v+'"]')?.classList.toggle('active',v===t)});document.getElementById('viewTitle').textContent=({profile:'Ficha de personaje',combat:'Mesa de combate',equipment:'Inventario y arsenal',spells:'Magia e invocaciones',companions:'Bestiario y acompañantes',progression:'El siguiente capítulo'})[t];document.body.classList.remove('menu-open');if(t==='spells')renderSpellsTab();if(t==='companions')renderCompanionsTab();renderSupplement();window.scrollTo({top:0,behavior:'smooth'})};
function exportSheet(){let b=new Blob([JSON.stringify({format:'lior-sheet-v3',character,inventory,spells,companions,logs},null,2)],{type:'application/json'});let a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='lior-respaldo.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function importSheet(file){if(!file)return;try{const s=JSON.parse(await file.text());if(s.format!=='lior-sheet-v3'||!s.character||!Array.isArray(s.inventory)||!Array.isArray(s.spells)||!Array.isArray(s.companions))throw Error('Formato no reconocido');if(!confirm('¿Reemplazar la ficha de este dispositivo con este respaldo?'))return;localStorage.setItem('lior_preimport',JSON.stringify({character,inventory,spells,companions,logs}));character=s.character;inventory=s.inventory;spells=s.spells;companions=s.companions;logs=s.logs||[];persist();renderAll();toast('Respaldo importado.')}catch(e){toast('No se pudo importar: '+e.message)}}
function undoLevel(){let raw=localStorage.getItem('lior_before_level');if(!raw)return toast('Todavía no hay una subida que restaurar.');if(!confirm('¿Restaurar el estado anterior a la última subida? Se reemplazará el estado actual.'))return;const s=JSON.parse(raw);character=s.character;spells=s.spells;persist();renderAll();toast('Estado anterior restaurado.')}
const oldConfirmLevel=confirmLevelUpWizard;
confirmLevelUpWizard=async function(){if(!levelUpDraft)return;const d=levelUpDraft;const wp=getWarlockProgression(d.chosenClass==='Brujo'?d.newClassLevel:character.combat_state.class_levels.Brujo);if(d.chosenClass!=='Brujo')return toast('Esta versión valida la progresión de brujo. La multiclase requiere completar su motor de reglas.');if(d.invocationsSelected.length!==wp.invocations)return toast('Selecciona exactamente '+wp.invocations+' invocaciones.');if(!Number.isFinite(computeDraftHpGain())||Number(d.hpRollValue)<1)return toast('Revisa los puntos de golpe.');let invs=d.invocationsSelected.map(id=>ELDRITCH_INVOCATIONS_CATALOG.find(i=>i.id===id));if(invs.some(i=>!i||i.minLevel>d.newClassLevel))return toast('Hay una invocación con requisitos de nivel pendientes.');if(doesDraftGrantASI()&&d.asiMode==='stats'){const add={};add[d.asiStat1]=(add[d.asiStat1]||0)+(d.asiSplit==='single'?2:1);if(d.asiSplit!=='single')add[d.asiStat2]=(add[d.asiStat2]||0)+1;if(Object.entries(add).some(([k,v])=>Number(character[k])+v>20))return toast('La mejora elegida excede 20 en una característica.');}if(wp.spellsKnown>getWarlockProgression(character.combat_state.class_levels.Brujo).spellsKnown&&!d.newSpellId)return toast('Selecciona el nuevo conjuro antes de confirmar.');localStorage.setItem('lior_before_level',JSON.stringify({character,spells}));let record={from:d.fromTotalLevel,to:d.toTotalLevel,class:d.chosenClass,hp:computeDraftHpGain(),date:new Date().toLocaleDateString('es')};if(d.newSpellId)spells.find(s=>s.id===d.newSpellId).is_known=true;await oldConfirmLevel();(character.combat_state.level_history||=[]).push(record);persist();renderAll();toast('Nivel actualizado y estado anterior respaldado.')};
const oldOpenWizard=openLevelUpWizard;
openLevelUpWizard=function(){oldOpenWizard(character.level+1)};
const originalSpellsRender=renderSpellsTab;
renderSpellsTab=function(){if(!document.getElementById('spellExtra'))return originalSpellsRender();let full=spells;spells=full.filter(s=>spellView==='catalog'||(spellView==='favorites'?s.is_equipped:s.is_known));try{originalSpellsRender()}finally{spells=full}document.querySelectorAll('#spellsGridContainer>div').forEach(card=>{let title=card.querySelector('h4')?.textContent;let sp=spells.find(s=>s.name===title);if(!sp)return;const footer=card.lastElementChild;let b=document.createElement('button');b.className='quiet-btn';b.textContent=sp.is_known?'Olvidar':'Aprender';b.onclick=()=>{sp.is_known=!sp.is_known;if(!sp.is_known)sp.is_equipped=false;persist();renderAll()};footer.prepend(b);card.querySelector('label').lastChild.textContent=' Favorito';});if(!document.getElementById('spellsGridContainer').children.length)document.getElementById('spellsGridContainer').innerHTML='<p class="muted">No hay conjuros en esta vista. Puedes añadirlos desde el catálogo.</p>'};
const oldToggleSpell=toggleEquipSpell;toggleEquipSpell=async function(id,v){let s=spells.find(s=>s.id===id);if(v&&!s.is_known){toast('Aprende el conjuro antes de marcarlo como favorito.');return renderSpellsTab()}await oldToggleSpell(id,v)};
