const oldCompRender=renderCompanionsTab;renderCompanionsTab=function(){if(!document.getElementById('compExtra'))return oldCompRender();const all=companions;companions=all.filter(c=>compView==='catalog'||c.is_summoned);try{oldCompRender()}finally{companions=all}};
function adjustHealth(mode){let amount=Number(document.getElementById('healthAmount').value);if(!Number.isFinite(amount)||amount<0)return;amount=Math.floor(amount);if(mode==='damage'){let absorbed=Math.min(character.hp_temp,amount);character.hp_temp-=absorbed;character.hp_current=Math.max(0,character.hp_current-(amount-absorbed))}else if(mode==='heal')character.hp_current=Math.min(character.hp_max,character.hp_current+amount);else character.hp_temp=Math.max(character.hp_temp,amount);persist();renderAll()}
