const originalProgression=getWarlockProgression;
getWarlockProgression=function(lvl){const r=originalProgression(lvl);r.extraAttacks=(character?.combat_state?.invocations_known||[]).includes('thirsting_blade')&&Number(lvl)>=5?2:1;return r};
const originalSmite=executeCastigoArcano;
