const originalCast=castSpellInCombat;
castSpellInCombat=async function(id){const sp=spells.find(s=>s.id===id);if(!sp)return;if(Number(sp.level)>5){const cs=character.combat_state;const arc=cs.arcanum||{};if(arc[sp.level]!==sp.name)return toast('Este conjuro no está seleccionado como Arcanum Místico.');cs.arcanum_used||={};if(cs.arcanum_used[sp.level])return toast('Este Arcanum está agotado hasta el próximo descanso largo.');cs.arcanum_used[sp.level]=true;cs.action_used=true;if(sp.concentration)cs.concentration_spell=sp.name;await addCombatLog('Arcanum Místico: '+sp.name);await saveCharacterCore();return}if(Number(sp.level)>getWarlockProgression(character.combat_state.class_levels.Brujo).slotLevel)return toast('Aún no tienes espacios del nivel necesario.');await originalCast(id)};
