/* V3: carried equipment, pact summons and custom companion actions. */
const TurnDesk={picker:null,query:'',result:null};
function migrateTurnDesk(){const cs=bCS();if(!cs.turn_desk_v3){inventory.forEach(i=>{i.is_carried=!i.is_pact_weapon&&Boolean(i.is_equipped);if(i.is_pact_weapon)i.is_equipped=false});let sword=inventory.find(i=>/espada.*(platin|platead)/i.test(i.name));if(!sword){sword={id:'lior-platinum-sword',name:'Espada platinada',category:'arma',subcategory:'Arma marcial',damage_dice:'1d8',damage_type:'Cortante',range_info:'5 pies',properties:'Versátil (1d10); platinada',magic_bonus:0,quantity:1,is_pact_weapon:false,is_equipped:true,is_carried:true,use_cha:true};inventory.push(sword)}else{sword.is_carried=true;sword.is_equipped=true;sword.is_pact_weapon=false;sword.use_cha=true}const dagger=inventory.find(i=>/^daga$/i.test(i.name));if(dagger){dagger.is_carried=true;dagger.is_equipped=true;dagger.is_pact_weapon=false}const harpoon=inventory.find(i=>/arpón/i.test(i.name));if(harpoon)harpoon.dm_rules={slow:10,slow_until:'Comienzo del siguiente turno del objetivo',withdraw_dice:'2d4',withdraw_cost:'action',withdraw_status:'Pendiente de confirmar con el DM'};const pet=companions.find(c=>/pourcoon|purcón|purcon/i.test(c.name));if(pet){pet.immunities='Veneno';pet.spike_count=12;pet.custom_actions=[{id:'spikes',name:'Púas',cost:'action',dice:'1d4',damage_type:'Perforante',attack_bonus:Number(pet.attack_bonus)||0,description:'Ataque de arma cuerpo a cuerpo.',critical:false,count:1},{id:'skin',name:'Piel de púas',cost:'passive',dice:'1d4',damage_type:'Perforante',description:'Al comienzo de su turno, inflige este daño a cualquier criatura que lo esté apresando.',critical:false,count:1},{id:'final',name:'Muerte final',cost:'action',dice:'1d4',damage_type:'Perforante',description:'Todas las púas salen despedidas. Cada una impacta con crítico, según la regla de tu mesa. El dado por púa queda editable.',critical:true,use_spikes:true}];pet.damage_dice='1d4';pet.attack_name='Púas';pet.damage_type='Perforante'}cs.battle.summonedWeaponId=null;cs.battle.harpoonTarget=null;cs.turn_desk_v3=true;persist()}}
function tdCarried(){return inventory.filter(i=>i.is_carried&&!i.is_pact_weapon)}
function tdWeaponMod(w){return w.is_pact_weapon||w.use_cha?getMod(character.cha):/sutil/i.test(w.properties||'')?Math.max(getMod(character.str),getMod(character.dex)):getMod(character.str)}
function tdDice(expr){const clean=String(expr||'').replace(/\s/g,'');if(!/^[+\-\ddD]+$/.test(clean)||!clean)return null;let parts=clean.match(/[+-]?[^+-]+/g)||[],average=0,count=0;for(let raw of parts){const minus=raw[0]==='-'?-1:1;const t=raw.replace(/^[+-]/,'');if(t.toLowerCase().includes('d')){let m=t.match(/^(\d*)d(\d+)$/i);if(!m||+m[2]<1)return null;let n=+(m[1]||1),s=+m[2];average+=minus*n*(s+1)/2;count+=n}else if(/^\d+$/.test(t))average+=minus*Number(t);else return null}return{average,count,formula:clean}}
function tdDamageBlock(expr,label='Daño estimado'){let d=tdDice(expr);return `<div class="damage-summary"><small>${esc(label)}</small><strong>${esc(expr)}</strong>${d?`<span>${d.count} ${d.count===1?'dado':'dados'} · Promedio ${Number(d.average.toFixed(2))}</span>`:''}</div>`}
function tdWeaponFormula(w,preview=true){const c=bCS(),p=bProg();let flat=tdWeaponMod(w)+(Number(w.magic_bonus)||0)+(c.hexblade_curse||preview&&Battle.options.curse?p.prof:0);let dice=w.damage_dice||'0';if(flat)dice+=sign(flat);if(c.concentration_spell?.toLowerCase().includes('maleficio')||preview&&Battle.options.hex)dice+='+1d6';if(w.is_pact_weapon&&c.invocations_known.includes('lifedrinker'))dice+=sign(getMod(character.cha));return dice}
function tdTile(w){return `<button class="ready-weapon" onclick="bSelect('weapon','${esc(w.id)}')">${bIcon(bKind(w))}<span><strong>${esc(bName(w))}</strong><small>${w.is_pact_weapon?'Invocada actualmente':'Arma física'}</small></span><span>→</span></button>`}
function tdMain(){const c=bCS();let physical=tdCarried().filter(i=>i.category==='arma'&&i.is_equipped);let summoned=inventory.find(i=>i.id===c.battle.summonedWeaponId);const tricks=spells.filter(s=>s.is_known&&Number(s.level)===0);return `<div class="ready-group"><div class="ready-heading"><h2>Armas disponibles</h2><span>Lo que tienes en las manos</span></div><div class="ready-weapons">${physical.map(tdTile).join('')}${summoned?tdTile(summoned):''}<button class="ready-weapon summon-tile" onclick="tdOpenPicker('summon')">${bIcon('magic')}<span><strong>Invocar arma</strong><small>${c.bonus_action_used?'Usar acción':'Usar acción adicional'} · Regla de mesa</small></span><span>＋</span></button></div>${c.battle.harpoonTarget?`<div class="harpoon-state"><span>Arpón clavado${c.battle.harpoonTarget.name?' en '+esc(c.battle.harpoonTarget.name):''} · ${c.battle.harpoonTarget.slow_active===false?'Ralentización terminada':'−'+c.battle.harpoonTarget.slow+' pies hasta su siguiente turno'}</span><button onclick="tdWithdrawPanel()">Retirar arpón →</button></div>`:''}</div><div class="ready-group"><div class="ready-heading"><h2>Magia inmediata</h2><span>Trucos y acceso a tus hechizos</span></div><div class="cantrip-deck">${tricks.map(s=>`<button class="cantrip-key" onclick="bSelect('spell','${esc(s.id)}')">${bIcon('magic')}<span>${esc(s.name.split(' (')[0])}</span></button>`).join('')}<button class="cantrip-key spell-choice" onclick="tdOpenPicker('spell')">${bIcon('magic')}<span>Elegir hechizo <small>Favoritos y conocidos</small></span><b>＋</b></button></div></div><div class="ready-group"><div class="ready-heading"><h2>Compañeros activos</h2><button class="condition-open" onclick="switchTab('companions')">Bestiario →</button></div><div class="ready-minions">${companions.filter(c=>c.is_summoned).map(m=>`<button class="ready-minion" onclick="bSelect('minion','${esc(m.id)}')">${bIcon('ghost')}<span><strong>${esc(/pourcoon|purcón/i.test(m.name)?'Pur Pur':m.name.split(' (')[0])}</strong><small>${m.hp_current} / ${m.hp_max} PG · Abrir acciones</small></span></button>`).join('')||'<span class="muted">Sin compañeros activos.</span>'}</div></div><div class="turn-quick-tools"><button class="quiet-btn" onclick="bFeature('hands')" ${c.action_used||c.healing_hands_used?'disabled':''}>Manos Curativas ${c.healing_hands_used?'· agotadas':''}</button><button class="quiet-btn" onclick="tdHealthPanel()">Daño / curación</button><button class="quiet-btn" onclick="bSection('features')">Capacidades y reacciones</button></div>`}
const tdOldMain=renderBattleMain;renderBattleMain=function(){if(Battle.section==='weapons')return tdMain();return '<button class="condition-open" onclick="bSection(\'weapons\')">← Volver al turno</button>'+tdOldMain()};
const tdOldSelect=bSelect;bSelect=function(t,id){TurnDesk.picker=null;TurnDesk.result=null;tdOldSelect(t,id)};
function tdOpenPicker(type){TurnDesk.picker=type;TurnDesk.query='';Battle.selection={type:'picker',id:type};Battle.pending=null;renderBattleComposer();if(window.innerWidth<901)document.getElementById('battleComposer').scrollIntoView({behavior:'smooth',block:'start'})}
function tdFilterPicker(v){TurnDesk.query=v;tdRenderPickerRows()}
function tdPickerRows(){const type=TurnDesk.picker,q=TurnDesk.query.toLowerCase().trim();let rows=type==='summon'?inventory.filter(w=>w.category==='arma'&&!w.catalog_source_id):spells.filter(s=>s.is_known&&Number(s.level)>0);if(q)rows=rows.filter(w=>w.name.toLowerCase().includes(q));else if(type==='summon')rows=rows.filter(w=>w.is_favorite_pact);else rows=rows.filter(w=>w.is_equipped);return rows.map(w=>`<button class="picker-row" onclick="${type==='summon'?"tdSummon('"+esc(w.id)+"')":"bSelect('spell','"+esc(w.id)+"')"}"><span><strong>${esc(w.name.split(' (')[0])}</strong><small>${type==='summon'?esc(w.damage_dice||'')+' · '+esc(w.range_info||''):esc(w.casting_time)+' · Nivel '+w.level}</small></span>→</button>`).join('')||'<p class="battle-subtext">Sin resultados. Busca por nombre o añade una opción en el catálogo.</p>'}
function tdRenderPickerRows(){const el=document.getElementById('tdPickerRows');if(el)el.innerHTML=tdPickerRows()}
function tdRenderPicker(){const summon=TurnDesk.picker==='summon',c=bCS();let cost=!c.bonus_action_used?'Acción adicional':!c.action_used?'Acción':'Sin acción disponible';document.getElementById('battleComposer').innerHTML=bHead(summon?'Pacto del Filo':'Grimorio',summon?'Invocar arma':'Elegir hechizo','')+`<div class="compose-body"><p class="battle-note">${summon?'Consume '+cost.toLowerCase()+'. Sustituye el arma invocada anterior. Coste personalizado de tu mesa.':'Se muestran tus favoritos. Busca entre tus hechizos conocidos.'}</p><input class="battle-search" style="margin-top:13px" aria-label="${summon?'Buscar arma para invocar':'Buscar hechizo conocido'}" placeholder="${summon?'Buscar cualquier arma del catálogo…':'Buscar hechizo conocido…'}" oninput="tdFilterPicker(this.value)"><p class="battle-kicker">${summon?'Tus formas favoritas':'Hechizos favoritos'}</p><div id="tdPickerRows" class="picker-list">${tdPickerRows()}</div><button class="condition-open" onclick="switchTab('${summon?'equipment':'spells'}')">${summon?'Equipo: catálogo y reglas →':'Administrar grimorio →'}</button></div>`}
async function tdSummon(id){let c=bCS();if(c.action_used&&c.bonus_action_used)return toast('Ya gastaste tu acción y tu acción adicional.');let source=inventory.find(w=>w.id===id);if(!source)return;let w=source;if(!source.is_pact_weapon){w=inventory.find(i=>i.catalog_source_id===source.id);if(!w){w={...source,id:'pact-form-'+source.id,catalog_source_id:source.id,is_pact_weapon:true,is_equipped:false,is_carried:false,magic_bonus:Math.max(Number(source.magic_bonus)||0,c.invocations_known.includes('improved_pact_weapon')?1:0)};inventory.push(w)}}const cost=c.bonus_action_used?'acción':'acción adicional';if(c.bonus_action_used)c.action_used=true;else c.bonus_action_used=true;c.battle.summonedWeaponId=w.id;character.active_pact_weapon_id=w.id;TurnDesk.picker=null;Battle.section='weapons';Battle.selection={type:'weapon',id:w.id};Battle.options={curse:false,hex:false};await bLog('Invocó '+w.name+' · '+cost+' (regla de mesa).');toast('Arma invocada. '+(cost==='acción adicional'?'Tu acción sigue disponible.':'Tu acción está gastada.'))}
const tdOriginalCompose=renderBattleComposer;renderBattleComposer=function(){if(!document.getElementById('battleComposer'))return;if(Battle.selection?.type==='picker'){tdRenderPicker();return}if(Battle.selection?.type==='withdraw'){tdRenderWithdraw();return}if(Battle.selection?.type==='health'){tdRenderHealth();return}if(Battle.selection?.type==='minion'){tdRenderMinion(Battle.selection.id);return}tdOriginalCompose();const s=Battle.selection;if(s?.type==='weapon'&&!Battle.pending){const w=inventory.find(i=>i.id===s.id);if(!w)return;const node=document.querySelector('#battleComposer .compose-body');node?.insertAdjacentHTML('afterbegin',tdDamageBlock(tdWeaponFormula(w),'Si impactas · antes de efectos posteriores'));if(w.dm_rules)node?.insertAdjacentHTML('beforeend',`<div class="dm-rule-note">Arpón del DM: al impactar, −${w.dm_rules.slow} pies hasta ${esc(w.dm_rules.slow_until).toLowerCase()}. Retirada: ${esc(w.dm_rules.withdraw_dice)} · ${w.dm_rules.withdraw_cost==='action'?'Acción':'Acción adicional'}. <small>${esc(w.dm_rules.withdraw_status)}</small></div>`)}if(s?.type==='spell'&&!Battle.pending){const sp=spells.find(x=>x.id===s.id);let expr=tdSpellFormula(sp);if(expr)document.querySelector('#battleComposer .compose-body')?.insertAdjacentHTML('afterbegin',tdDamageBlock(expr,/descarga sobrenatural/i.test(sp.name)?'Si todos los rayos impactan':Number(sp.level)===0?'Daño del ataque':'Referencia de daño'))}};
function tdSpellFormula(sp){if(!sp)return null;const c=bCS(),t=character.level<5?1:character.level<11?2:character.level<17?3:4;if(/descarga sobrenatural/i.test(sp.name)){let flat=(c.invocations_known.includes('agonizing_blast')?getMod(character.cha):0)+(c.hexblade_curse||Battle.options.curse?bProg().prof:0);let f=t+'d10'+(flat?sign(flat*t):'');if(c.concentration_spell?.toLowerCase().includes('maleficio')||Battle.options.hex)f+='+'+t+'d6';return f}if(/toque helado/i.test(sp.name))return t+'d8'+((c.hexblade_curse||Battle.options.curse)?sign(bProg().prof):'')+((c.concentration_spell?.toLowerCase().includes('maleficio')||Battle.options.hex)?'+1d6':'');return tdDice(sp.damage_dice)?sp.damage_dice:null}
const tdExecuteWeapon=bExecuteWeapon;bExecuteWeapon=async function(){let w=inventory.find(w=>w.id===Battle.selection?.id);if(!w)return;if(w.is_pact_weapon&&bCS().battle.summonedWeaponId!==w.id)return toast('Primero debes invocar esta arma.');let before=bCS().battle.attacksMade;await tdExecuteWeapon();if(bCS().battle.attacksMade>before&&Battle.pending){Battle.pending.weaponId=w.id;Battle.pending.formula=tdWeaponFormula(w,false);renderBattleComposer()}};
const tdImpactRender=bRenderImpact;bRenderImpact=function(a){tdImpactRender(a);let el=document.querySelector('#battleComposer .compose-body');el?.insertAdjacentHTML('afterbegin',tdDamageBlock(a.formula,'Daño base del impacto'));const w=inventory.find(x=>x.id===a.weaponId);if(w?.dm_rules){el?.insertAdjacentHTML('beforeend',`<div class="harpoon-confirm"><label>Objetivo alcanzado (opcional)<input id="tdHarpoonTarget" placeholder="Nombre del objetivo"></label><button class="quiet-btn" onclick="tdLodgeHarpoon('${esc(w.id)}')">Registrar arpón clavado</button><p class="battle-subtext">−${w.dm_rules.slow} pies hasta ${esc(w.dm_rules.slow_until).toLowerCase()}.</p></div>`)}};
function tdLodgeHarpoon(id){let w=inventory.find(x=>x.id===id);bCS().battle.harpoonTarget={weaponId:id,name:document.getElementById('tdHarpoonTarget')?.value||'',slow:w.dm_rules.slow,slow_active:true};persist();toast('Arpón clavado registrado.');renderBattle();if(Battle.selection?.type==='impact')bRenderImpact(Battle.selection.attack)}
function tdWithdrawPanel(){Battle.selection={type:'withdraw'};Battle.pending=null;renderBattleComposer()}
function tdRenderWithdraw(){const c=bCS(),target=c.battle.harpoonTarget;if(!target){Battle.selection=null;return renderBattle()}const w=inventory.find(x=>x.id===target.weaponId),r=w?.dm_rules||{withdraw_dice:'2d4',withdraw_cost:'action',withdraw_status:'Pendiente de confirmar con el DM'};const cost=r.withdraw_cost==='bonus'?'bonus_action_used':'action_used';document.getElementById('battleComposer').innerHTML=bHead('Arpón del DM','Retirar arpón',`<span>${cost==='action_used'?'Acción':'Acción adicional'}</span>`)+`<div class="compose-body">${tdDamageBlock(r.withdraw_dice)}<p class="battle-note">${esc(r.withdraw_status)}. Este daño y su coste se pueden editar en Equipo.</p><button class="action-commit" ${c[cost]?'disabled':''} onclick="tdWithdraw()">${c[cost]?'Acción necesaria gastada':'Retirar y registrar daño'}</button><button class="condition-open" onclick="bCS().battle.harpoonTarget.slow_active=false;persist();renderBattle();tdRenderWithdraw()">Registrar inicio del turno del objetivo (termina ralentización)</button><button class="condition-open" onclick="bCS().battle.harpoonTarget=null;persist();renderBattle();Battle.selection=null;renderBattleComposer()">Quitar seguimiento sin retirar</button></div>`}
async function tdWithdraw(){let c=bCS(),target=c.battle.harpoonTarget;if(!target)return;let r=inventory.find(x=>x.id===target.weaponId)?.dm_rules||{withdraw_cost:'action',withdraw_dice:'2d4'},key=r.withdraw_cost==='bonus'?'bonus_action_used':'action_used';if(c[key])return;c[key]=true;c.battle.harpoonTarget=null;Battle.selection=null;await bLog('Retiró el arpón'+(target.name?' de '+target.name:'')+': '+r.withdraw_dice+' perforante (regla del DM).')}
function tdHealthPanel(){Battle.selection={type:'health'};Battle.pending=null;renderBattleComposer()}
function tdRenderHealth(){document.getElementById('battleComposer').innerHTML=bHead('Puntos de golpe','Daño y curación','')+`<div class="compose-body"><label>Cantidad<input class="battle-search" id="tdHPAmount" type="number" min="0" value="1" aria-label="Cantidad de PG"></label><div class="health-buttons"><button class="quiet-btn" onclick="tdHP('damage')">Recibir daño</button><button class="quiet-btn" onclick="tdHP('heal')">Curar</button><button class="quiet-btn" onclick="tdHP('temp')">PG temporales</button></div><p class="battle-subtext">El daño consume primero los PG temporales. La curación no supera los PG máximos.</p></div>`}
function tdHP(mode){let n=Math.max(0,Math.floor(Number(document.getElementById('tdHPAmount').value)||0));if(mode==='damage'){let temp=Math.min(n,character.hp_temp);character.hp_temp-=temp;character.hp_current=Math.max(0,character.hp_current-(n-temp))}else if(mode==='heal')character.hp_current=Math.min(character.hp_max,character.hp_current+n);else character.hp_temp=Math.max(character.hp_temp,n);persist();renderAll();toast('Puntos de golpe actualizados.')}
function tdMinionFormula(m,a){let base=tdDice(a.dice);if(!base)return a.dice||'Sin daño';let count=a.use_spikes?Number(m.spike_count)||0:Number(a.count)||1;const multiplier=count*(a.critical?2:1);let expr=String(a.dice).replace(/(\d*)d(\d+)/gi,(_,n,d)=>(Number(n||1)*multiplier)+'d'+d);if(count>1)expr=expr.replace(/([+-])(\d+)(?![\dd])/g,(_,sign,n)=>sign+(Number(n)*count));return expr}
function tdRenderMinion(id){let m=companions.find(x=>x.id===id);if(!m)return;let actions=m.custom_actions||[{id:'default',name:m.attack_name,dice:m.damage_dice,cost:'action',damage_type:m.damage_type,description:m.special_traits}];const used=bCS().battle.minionActions?.[id];document.getElementById('battleComposer').innerHTML=bHead('Compañero activo',/pourcoon|purcón/i.test(m.name)?'Pur Pur':m.name.split(' (')[0],`<span>${m.hp_current}/${m.hp_max} PG</span><span>CA ${m.ac}</span>`)+`<div class="compose-body">${m.immunities?'<span class="condition-mark">Inmunidad: '+esc(m.immunities)+'</span>':''}${m.spike_count!==undefined?'<span class="condition-mark">'+m.spike_count+' púas actuales</span>':''}<div class="minion-action-list">${actions.map((a,index)=>`<div class="minion-action"><strong>${esc(a.name)}</strong><small>${a.cost==='passive'?'Rasgo al inicio de su turno':a.cost==='reaction'?'Reacción':'Acción'}${a.critical?' · Crítico garantizado (DM)':''}${a.attack_bonus!==undefined&&a.cost!=='passive'&&!a.critical?' · Impacto '+sign(a.attack_bonus):''}</small><p>${esc(a.description||'')}</p>${tdDamageBlock(tdMinionFormula(m,a),a.use_spikes?'Todas las púas · cálculo editable':'Daño')}<button class="quiet-btn" ${a.cost==='action'&&used?'disabled':''} onclick="tdMinionAction('${esc(id)}',${index})">${a.cost==='passive'?'Registrar rasgo':used&&a.cost==='action'?'Acción registrada':'Registrar '+esc(a.name)}</button></div>`).join('')}</div><details class="battle-options"><summary>PG del compañero</summary><input type="number" min="0" max="${m.hp_max}" value="${m.hp_current}" onchange="bMinionHP('${esc(m.id)}',this.value)"></details><button class="condition-open" onclick="openCompanionModal('${esc(m.id)}')">Editar rasgos, púas y acciones →</button><p class="battle-subtext">Las acciones del compañero se llevan separadas de las de Lior.</p></div>`}
async function tdMinionAction(id,index){const m=companions.find(x=>x.id===id);const a=(m.custom_actions||[{name:m.attack_name,dice:m.damage_dice,cost:'action'}])[index];if(!a)return;let c=bCS();c.battle.minionActions||={};if(a.cost==='action'&&c.battle.minionActions[id])return;if(a.cost==='action')c.battle.minionActions[id]=true;await bLog(m.name+' · '+a.name+': '+tdMinionFormula(m,a)+(a.critical?' (críticos del DM)':'')+'.')}
const tdOldNext=bNextTurn;bNextTurn=async function(){bCS().battle.minionActions={};TurnDesk.result=null;await tdOldNext()};
