function tdInventoryCard(i,carried=false){return `<article class="equipment-card"><span class="eyebrow">${esc(i.subcategory||i.category)}</span><h3>${esc(i.name)}</h3><p>${esc(i.damage_dice?i.damage_dice+' '+(i.damage_type||''):i.properties||'')}</p>${i.notes?'<details><summary>Notas</summary><p>'+esc(i.notes)+'</p></details>':''}<div class="item-flags">${i.is_pact_weapon?`<label><input type="checkbox" ${i.is_favorite_pact?'checked':''} onchange="tdFavorite('${esc(i.id)}',this.checked)"> Forma favorita</label>`:`<label><input type="checkbox" ${i.is_carried?'checked':''} onchange="tdSetCarried('${esc(i.id)}',this.checked)"> Lo llevo</label>${i.is_carried?`<label><input type="checkbox" ${i.is_equipped?'checked':''} onchange="tdEquip('${esc(i.id)}',this.checked)"> Equipado</label>`:''}`}</div>${carried&&!i.is_pact_weapon?`<label class="quantity-field">Cantidad <input type="number" min="0" value="${i.quantity||1}" onchange="tdQuantity('${esc(i.id)}',this.value)"></label>`:''}<div class="item-card-footer"><button onclick="openItemModal('${esc(i.id)}')">Editar</button>${carried&&!i.is_pact_weapon?`<button onclick="tdSetCarried('${esc(i.id)}',false)">Guardar en catálogo</button>`:''}</div></article>`}
const tdOldInventoryRender=renderInventoryTab;
renderInventoryTab=function(){tdOldInventoryRender();if(!document.getElementById('tdCarriedGrid'))return;const q=(document.getElementById('invSearchInput').value||'').toLowerCase().trim(),cat=document.getElementById('invCategoryFilter').value;let rows=q?inventory.filter(i=>!i.catalog_source_id&&(i.name+' '+(i.properties||'')).toLowerCase().includes(q)&&(cat==='all'||i.category===cat)):[];document.getElementById('inventoryTableContainer').innerHTML=q?`<p class="battle-subtext" style="margin-bottom:16px">${rows.length} resultados del catálogo incluido</p><div class="equipment-grid">${rows.map(i=>tdInventoryCard(i)).join('')}</div>`:'<div class="catalog-empty">'+bIcon('blade')+'<h2>Busca tu equipo</h2><p>Armas, armaduras, herramientas y objetos. Añade lo que llevas a tu Inventario o marca las formas favoritas del pacto.</p><p class="battle-subtext">También puedes crear o editar equipo de tu mesa.</p></div>';tdRenderCarried()};
function tdRenderCarried(){const host=document.getElementById('tdCarriedGrid');if(!host)return;const items=tdCarried();host.innerHTML=['arma','armadura','escudo','herramienta','objeto'].map(cat=>{let rows=items.filter(i=>i.category===cat);return rows.length?`<section class="carry-category"><h2>${({arma:'Armas físicas',armadura:'Armadura',escudo:'Escudos',herramienta:'Herramientas',objeto:'Mochila y consumibles'})[cat]}</h2><div class="equipment-grid">${rows.map(i=>tdInventoryCard(i,true)).join('')}</div></section>`:''}).join('')+`<section class="carry-category"><h2>Formas favoritas del pacto</h2><p class="battle-subtext">Estas formas no son objetos físicos en tu mochila. Invócalas durante el combate.</p><div class="equipment-grid" style="margin-top:12px">${inventory.filter(i=>i.is_pact_weapon&&i.is_favorite_pact).map(i=>tdInventoryCard(i)).join('')}</div></section>`}
const tdOldSwitch=switchTab;switchTab=function(t){document.getElementById('tab-carried')?.classList.add('hidden');document.querySelector('[data-view="carried"]')?.classList.remove('active');if(t==='carried'){tdOldSwitch('equipment');document.getElementById('tab-equipment').classList.add('hidden');document.getElementById('tab-carried').classList.remove('hidden');document.querySelector('[data-view="equipment"]').classList.remove('active');document.querySelector('[data-view="carried"]').classList.add('active');document.getElementById('viewTitle').textContent='Lo que lleva Lior';tdRenderCarried();return}tdOldSwitch(t);if(t==='equipment')document.getElementById('viewTitle').textContent='Equipo · Catálogo';if(t==='combat')document.getElementById('viewTitle').textContent='Tu turno'};
let tdCompDraft=[];
function tdActionEditor(){document.getElementById('tdActionsEditor').innerHTML=tdCompDraft.map((a,i)=>`<div class="custom-action-editor" data-action-index="${i}"><div class="field-grid"><label>Nombre<input data-key="name" value="${esc(a.name)}"></label><label>Momento / coste<select data-key="cost">${[['action','Acción'],['bonus','Acción adicional'],['reaction','Reacción'],['passive','Inicio de turno / rasgo']].map(([v,l])=>`<option value="${v}" ${a.cost===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Dados por impacto o púa<input data-key="dice" value="${esc(a.dice||'')}"></label><label>Tipo de daño<input data-key="damage_type" value="${esc(a.damage_type||'')}"></label><label>Bono de ataque<input data-key="attack_bonus" type="number" value="${a.attack_bonus??0}"></label><label>Número de impactos<input data-key="count" type="number" min="1" value="${a.count||1}"></label><label class="wide-field">Descripción<textarea data-key="description">${esc(a.description||'')}</textarea></label></div><div class="item-flags"><label><input data-key="critical" type="checkbox" ${a.critical?'checked':''}> Crítico garantizado (regla DM)</label><label><input data-key="use_spikes" type="checkbox" ${a.use_spikes?'checked':''}> Usar cantidad actual de púas</label></div><button type="button" class="condition-open" onclick="tdReadActions();tdCompDraft.splice(${i},1);tdActionEditor()">Quitar acción</button></div>`).join('')}
function tdReadActions(){tdCompDraft=[...document.querySelectorAll('#tdActionsEditor [data-action-index]')].map((row,i)=>{let a={id:tdCompDraft[i]?.id||'custom-'+Date.now()+'-'+i};row.querySelectorAll('[data-key]').forEach(el=>{let k=el.dataset.key;a[k]=el.type==='checkbox'?el.checked:['attack_bonus','count'].includes(k)?Number(el.value):el.value});return a})}
const tdOldCompModal=openCompanionModal;openCompanionModal=function(id=null){tdOldCompModal(id);const m=companions.find(c=>c.id===id)||{};tdCompDraft=JSON.parse(JSON.stringify(m.custom_actions||[{id:'default',name:m.attack_name||'Ataque',dice:m.damage_dice||'1d4',cost:'action',damage_type:m.damage_type||'',description:'',count:1,attack_bonus:m.attack_bonus||0}]));let more=document.createElement('div');more.className='custom-rules-editor';more.innerHTML=`<h3>Reglas del compañero · Editables con el DM</h3><div class="field-grid"><label>Inmunidades<input id="tdImmunities" value="${esc(m.immunities||'')}"></label><label>Púas actuales<input type="number" min="0" id="tdSpikes" value="${m.spike_count??0}"></label></div><h3 style="margin-top:18px">Acciones y rasgos</h3><div id="tdActionsEditor"></div><button class="quiet-btn" type="button" onclick="tdReadActions();tdCompDraft.push({name:'Nueva acción',cost:'action',dice:'1d4',damage_type:'',count:1});tdActionEditor()">Añadir acción o rasgo</button><p class="battle-subtext">Los críticos duplican los dados, no los modificadores. En Muerte final, el dado por púa es una base editable para confirmar con tu DM.</p>`;document.getElementById('modalBody').append(more);tdActionEditor();const save=document.getElementById('modalSaveBtn').onclick;document.getElementById('modalSaveBtn').onclick=async()=>{tdReadActions();if(tdCompDraft.some(a=>a.dice&&!tdDice(a.dice)))return toast('Revisa los dados de las acciones: por ejemplo 1d4 o 2d6+3.');const extra={immunities:document.getElementById('tdImmunities').value,spike_count:Math.max(0,Number(document.getElementById('tdSpikes').value)||0),custom_actions:JSON.parse(JSON.stringify(tdCompDraft))};await save();const target=id?companions.find(x=>x.id===id):companions[0];Object.assign(target,extra);persist();renderAll()}};
const tdOldItemModal=openItemModal;openItemModal=function(id=null){tdOldItemModal(id);const item=inventory.find(i=>i.id===id)||{};let div=document.createElement('div');div.className='custom-rules-editor';div.innerHTML=`<h3>Uso y posesión</h3><div class="item-flags"><label><input id="tdItemCarried" type="checkbox" ${item.is_carried?'checked':''}> Lo llevo físicamente</label><label><input id="tdItemPact" type="checkbox" ${item.is_pact_weapon?'checked':''}> Forma invocable</label><label><input id="tdItemCha" type="checkbox" ${item.use_cha?'checked':''}> Usa Carisma (vínculo)</label></div><label class="battle-subtext">Notas / procedencia<textarea id="tdItemNotes" class="battle-search">${esc(item.notes||'')}</textarea></label>${item.dm_rules||/arpón/i.test(item.name||'')?`<h3>Reglas del arpón · DM</h3><div class="field-grid"><label>Reducción de velocidad (pies)<input id="tdSlow" type="number" min="0" value="${item.dm_rules?.slow??10}"></label><label>Finaliza al…<input id="tdSlowUntil" value="${esc(item.dm_rules?.slow_until||'Comienzo del siguiente turno del objetivo')}"></label><label>Daño de retirada<input id="tdWithdrawDice" value="${esc(item.dm_rules?.withdraw_dice||'2d4')}"></label><label>Coste de retirada<select id="tdWithdrawCost"><option value="action">Acción</option><option value="bonus" ${item.dm_rules?.withdraw_cost==='bonus'?'selected':''}>Acción adicional</option></select></label><label>Acuerdo con el DM<input id="tdWithdrawStatus" value="${esc(item.dm_rules?.withdraw_status||'Pendiente de confirmar con el DM')}"></label></div>`:''}`;document.getElementById('modalBody').append(div);const save=document.getElementById('modalSaveBtn').onclick;document.getElementById('modalSaveBtn').onclick=async()=>{const extra={is_carried:document.getElementById('tdItemCarried').checked,is_pact_weapon:document.getElementById('tdItemPact').checked,use_cha:document.getElementById('tdItemCha').checked,notes:document.getElementById('tdItemNotes').value};if(document.getElementById('tdSlow')){if(!tdDice(document.getElementById('tdWithdrawDice').value))return toast('Revisa los dados de retirada.');extra.dm_rules={slow:Math.max(0,Number(document.getElementById('tdSlow').value)||0),slow_until:document.getElementById('tdSlowUntil').value,withdraw_dice:document.getElementById('tdWithdrawDice').value,withdraw_cost:document.getElementById('tdWithdrawCost').value,withdraw_status:document.getElementById('tdWithdrawStatus').value}}await save();const target=id?inventory.find(i=>i.id===id):inventory[0];Object.assign(target,extra);if(target.is_pact_weapon){target.is_carried=false;target.is_equipped=false}persist();renderAll()}};
const tdPreviousRender=renderAll;renderAll=function(){tdPreviousRender();if(document.getElementById('tdCarriedGrid'))tdRenderCarried();document.getElementById('tdInitiativeValue')&&(document.getElementById('tdInitiativeValue').textContent=sign(getMod(character.dex)+Number(profile().initiativeBonus||0)))};
document.addEventListener('DOMContentLoaded',()=>{migrateTurnDesk();document.querySelector('.battle-tabs').style.display='none';const carried=document.createElement('section');carried.id='tab-carried';carried.className='hidden';carried.innerHTML=`<div class="carry-intro"><p class="muted">Equipo que llevas, organizado por uso. Las formas del pacto se muestran aparte.</p><button class="quiet-btn" onclick="switchTab('equipment')">Buscar en Equipo →</button></div><div id="tdCoinHost"></div><div id="tdCarriedGrid"></div>`;document.querySelector('main').append(carried);const coin=document.getElementById('coin-cp').parentElement.parentElement;coin.classList.add('compact-coins');document.getElementById('tdCoinHost').append(coin);const nav=document.querySelector('.side-nav');let b=document.createElement('button');b.dataset.view='carried';b.onclick=()=>switchTab('carried');b.innerHTML='<small>05</small>Inventario';nav.querySelector('[data-view="equipment"]').innerHTML='<small>04</small>Equipo';nav.querySelector('[data-view="equipment"]').after(b);nav.querySelector('[data-view="companions"] small').textContent='06';nav.querySelector('[data-view="progression"] small').textContent='07';document.querySelector('#tab-equipment h2').textContent='Equipo · Catálogo';document.querySelector('#tab-equipment h2').nextElementSibling.textContent='Busca un objeto para añadirlo a lo que llevas, marcar una forma del pacto o editar sus reglas.';let init=document.createElement('div');init.className='td-header-init';init.innerHTML='<small>INICIATIVA</small><strong id="tdInitiativeValue"></strong>';document.querySelector('header .max-w-7xl>div>div:last-child').append(init);document.querySelectorAll('.battle-compose').forEach(n=>n.classList.add('td-composer'));Battle.section='weapons';Battle.selection=null;renderAll();switchTab('combat');});
const tdOldHit=bHitEffect;bHitEffect=async function(which){const c=bCS(),a=Battle.selection?.attack;const before=which==='smite'?c.battle.smiteUsed:c.battle.shroudDamageUsed;await tdOldHit(which);if(a&&!before&&(which==='smite'?c.battle.smiteUsed:c.battle.shroudDamageUsed)){a.appliedEffects||=[];a.appliedEffects.push(which==='smite'?bProg().smiteDice:String(character.level));bRenderImpact(a)}};
bRenderImpact=function(a){const c=bCS(),p=bProg(),w=inventory.find(x=>x.id===a.weaponId);let formula=a.formula+(a.appliedEffects||[]).map(f=>'+'+f).join('');let smite=a.pact&&c.invocations_known.includes('eldritch_smite')&&!c.battle.smiteUsed&&bSlots()>0,shroud=c.necrotic_shroud_active&&!c.battle.shroudDamageUsed;document.getElementById('battleComposer').innerHTML=bHead('Impacto confirmado',a.name,'')+`<div class="compose-body">${tdDamageBlock(formula,'Suma de daño · efectos aplicados')}${smite?`<button class="picker-row" style="width:100%;margin:10px 0" onclick="bHitEffect('smite')"><span><strong>Añadir Castigo Arcano</strong><small>+${p.smiteDice} fuerza · Espacio de pacto</small></span>＋</button>`:''}${shroud?`<button class="picker-row" style="width:100%;margin:10px 0" onclick="bHitEffect('shroud')"><span><strong>Añadir daño de Mortaja</strong><small>+${character.level} necrótico · Una vez por turno</small></span>＋</button>`:''}${w?.dm_rules?`<div class="harpoon-confirm"><label>Objetivo alcanzado (opcional)<input id="tdHarpoonTarget" placeholder="Nombre del objetivo"></label><button class="quiet-btn" onclick="tdLodgeHarpoon('${esc(w.id)}')">Registrar arpón clavado</button><p class="battle-subtext">−${w.dm_rules.slow} pies hasta ${esc(w.dm_rules.slow_until).toLowerCase()}.</p></div>`:''}<button class="action-commit" onclick="Battle.selection=null;renderBattle()">Listo</button></div>`};
const tdPetRender=tdRenderMinion;tdRenderMinion=function(id){tdPetRender(id);const m=companions.find(x=>x.id===id);let used=bCS().battle.minionActions?.[id];if(typeof used==='boolean')used={action:used};let cards=document.querySelectorAll('#battleComposer .minion-action');(m.custom_actions||[]).forEach((a,i)=>{let btn=cards[i]?.querySelector('button');if(!btn)return;const spent=used?.[a.cost];btn.disabled=!!spent||(a.use_spikes&&Number(m.spike_count)<=0);btn.textContent=spent?'Ya registrado':a.use_spikes&&Number(m.spike_count)<=0?'Sin púas':a.cost==='passive'?'Registrar rasgo':'Registrar '+a.name});const body=document.querySelector('#battleComposer .compose-body');body.insertAdjacentHTML('afterbegin',`<div class="minion-turn-controls"><button class="quiet-btn" onclick="tdMinionTurn('${esc(id)}')">Comenzar su turno ↻</button>${(m.custom_actions||[]).some(a=>a.id==='skin')?`<label><input type="checkbox" ${m.grappled?'checked':''} onchange="companions.find(c=>c.id==='${esc(id)}').grappled=this.checked;persist()"> Está apresado</label>`:''}</div>`)};
async function tdMinionTurn(id){const m=companions.find(x=>x.id===id);bCS().battle.minionActions||={};bCS().battle.minionActions[id]={};let skin=m.custom_actions?.find(a=>a.id==='skin');if(m.grappled&&skin){bCS().battle.minionActions[id].passive=true;await bLog(m.name+' · Inicio de turno: '+skin.name+' inflige '+tdMinionFormula(m,skin)+' a cada criatura que lo esté apresando.')}else await bLog('Comienza el turno de '+m.name+'.');renderBattleComposer()}
tdMinionAction=async function(id,index){const m=companions.find(x=>x.id===id),a=(m.custom_actions||[{name:m.attack_name,dice:m.damage_dice,cost:'action'}])[index];if(!a)return;let c=bCS();c.battle.minionActions||={};let used=c.battle.minionActions[id];if(!used||typeof used==='boolean')used=c.battle.minionActions[id]={action:Boolean(used)};if(used[a.cost]||a.use_spikes&&Number(m.spike_count)<=0)return;used[a.cost]=true;const formula=tdMinionFormula(m,a);if(a.use_spikes)m.spike_count=0;await bLog(m.name+' · '+a.name+': '+formula+(a.critical?' (críticos del DM)':'')+'.'+(a.use_spikes?' Púas actuales agotadas.':''))};
