const tdOldSpellFormula=tdSpellFormula;tdSpellFormula=function(sp){if(!sp)return null;let level=bProg().slotLevel;if(/infligir heridas/i.test(sp.name))return (2+level)+'d10';if(/susurros disonantes/i.test(sp.name))return (2+level)+'d6';if(/castigo marcador/i.test(sp.name))return level+'d6';return tdOldSpellFormula(sp)};
