tdWithdraw=async function(){let c=bCS(),t=c.battle.harpoonTarget;if(!t)return;let r=inventory.find(x=>x.id===t.weaponId)?.dm_rules||{},key=r.withdraw_cost==='bonus'?'bonus_action_used':'action_used';if(c[key]||c.battle.extractionAttempt?.pending)return;c[key]=true;c.battle.extractionAttempt={pending:true,weaponId:t.weaponId};await bLog('Intentó extraer el arpón: gasta '+(key==='action_used'?'acción':'acción adicional')+'; prueba de Fuerza 1d20 '+sign(getMod(character.str))+'.');tdRenderWithdraw()};
