const CLOUD_PENDING_KEY='lior_cloud_pending_v4';
async function cloudRequest(path,method='GET',body){const r=await fetch(SUPABASE_URL+'/rest/v1/'+path,{method,headers:{apikey:SUPABASE_KEY,'Content-Type':'application/json',Prefer:'return=representation'},...(body!==undefined?{body:JSON.stringify(body)}:{})});const txt=await r.text();let data;try{data=txt?JSON.parse(txt):null}catch{data=null}if(!r.ok)throw Error(data?.message||'Error HTTP '+r.status);return data}
function cloudStatus(message,type='saved'){const el=document.getElementById('cloudSaveStatus');if(el){el.textContent=message;el.dataset.state=type}const small=document.querySelector('.side-bottom>p:last-child');if(small)small.textContent=message;const retry=document.getElementById('cloudRetry');if(retry)retry.hidden=!['error','offline','conflict'].includes(type)}
function cloudSnapshot(){return JSON.parse(JSON.stringify({character,inventory,spells,companions,logs:logs.slice(0,100)}))}
function cloudPending(snapshot){try{localStorage.setItem(CLOUD_PENDING_KEY,JSON.stringify({rowId:CloudSheet.rowId,baseUpdatedAt:CloudSheet.updatedAt,snapshot}))}catch{cloudStatus('No se pudo preparar el guardado','error')}}
function cloudQueue(){if(!CloudSheet.ready||CloudSheet.loading)return;CloudSheet.dirty=true;CloudSheet.generation++;cloudPending(cloudSnapshot());cloudStatus('Guardando en la base de datos…','saving');queueMicrotask(()=>cloudFlush())}
const cloudOldLocal=saveLocalBackup;saveLocalBackup=function(){cloudOldLocal();cloudQueue()};
// Keep old table writers disabled: the entire sheet is committed atomically on its character row.
// This also preserves custom inventory and companion fields without requiring SQL migrations.
