// The load routine commits this once, then respects later player edits.
const detailsCloudLoad=cloudLoad;cloudLoad=async function(){await detailsCloudLoad();if(CloudSheet.ready&&detailImportPending){detailImportPending=false;renderAll();if(!CloudSheet.error)cloudQueue()}};
function renderQuickSheetStrip(){const el=document.getElementById('quickSheetStrip');if(!el)return;const ac=calculateDynamicAC(),armor=inventory.find(i=>i.is_carried&&i.is_equipped&&i.category==='armadura'),shield=inventory.find(i=>i.is_carried&&i.is_equipped&&i.category==='escudo');el.innerHTML=`<button class="quick-armor" onclick="toggleQuickSheet('armor')"><span>ARMADURA · CA ${ac.total}</span><small>${esc(armor?.name||'Sin armadura')}${shield?' · '+esc(shield.name):''} ↗</small></button><button class="quick-heal" onclick="toggleQuickSheet('heal')">＋ Curar heridas</button><button class="quick-gear" onclick="toggleQuickSheet('gear')">Equipo a mano ↗</button>`}
function toggleQuickSheet(mode){const el=document.getElementById('quickSheetPanel');if(el.dataset.mode===mode&&!el.hidden){el.hidden=true;return}el.hidden=false;el.dataset.mode=mode;renderQuickSheetPanel(mode)}
function closeQuickSheet(){document.getElementById('quickSheetPanel').hidden=true}
function renderQuickSheetPanel(mode){const el=document.getElementById('quickSheetPanel');if(!el)return;let close='<button class="quick-close" onclick="closeQuickSheet()" aria-label="Cerrar acceso rápido">×</button>';if(mode==='armor'){let armor=inventory.filter(i=>i.is_carried&&i.is_equipped&&['armadura','escudo'].includes(i.category));el.innerHTML=close+`<h2>Armadura de Lior · CA ${calculateDynamicAC().total}</h2><p class="armor-formula">${esc(calculateDynamicAC().breakdown)}</p><div class="quick-equipment-list">${armor.map(i=>`<div><strong>${esc(i.name)}</strong><p>${esc(i.properties||'')}</p><button onclick="openItemModal('${esc(i.id)}')">Ver / editar equipo</button></div>`).join('')}</div><p class="battle-subtext">Competencias: ${esc(profile().armorProficiencies||'')}</p>`}else if(mode==='heal'){const c=bCS();el.innerHTML=close+`<h2>Curar heridas</h2><p class="battle-subtext">Registrar PG recuperados. No lanza un conjuro ni gasta espacios.</p><div class="quick-heal-form"><label>Puntos recuperados<input id="quickHealAmount" type="number" min="1" value="1" aria-label="Puntos de curación recibida"></label><button onclick="applyQuickHealing()">Aplicar curación</button><span>${character.hp_current} / ${character.hp_max} PG</span></div><button class="quiet-btn" ${c.action_used||c.healing_hands_used?'disabled':''} onclick="quickHealingHands()">Manos Curativas · ${c.healing_hands_used?'agotadas':character.level+' PG · acción'}</button>${bKnown('curar heridas')?`<button class="quiet-btn" onclick="closeQuickSheet();bSelect('spell','${esc(bKnown('curar heridas').id)}')">Lanzar conjuro Curar heridas</button>`:''}`}else{const gear=tdCarried().filter(i=>i.category!=='arma');el.innerHTML=close+`<h2>Equipo que llevas</h2><div class="quick-equipment-list">${gear.map(i=>`<div><strong>${esc(i.name)}</strong><p>${Number(i.quantity)||1} ${i.healing_dice?'· Curación '+esc(i.healing_dice):''}</p><button onclick="openItemModal('${esc(i.id)}')">Ver / editar</button></div>`).join('')}</div><button class="quiet-btn" onclick="switchTab('carried')">Inventario completo →</button>`}}
function quickHealingAmount(current,max,amount){return Math.min(max,Math.max(0,current)+Math.max(0,Math.floor(amount)))}
function applyQuickHealing(){const input=document.getElementById('quickHealAmount'),amount=Number(input.value);if(!Number.isFinite(amount)||amount<1)return toast('Indica cuántos PG recuperaste.');const before=character.hp_current;character.hp_current=quickHealingAmount(character.hp_current,character.hp_max,amount);persist();renderAll();renderQuickSheetPanel('heal');toast('Recuperó '+(character.hp_current-before)+' PG.')}
async function quickHealingHands(){await bFeature('hands');renderQuickSheetPanel('heal')}
const detailsOldInventoryCard=tdInventoryCard;tdInventoryCard=function(i,carried){let html=detailsOldInventoryCard(i,carried);if(i.source_note)html=html.replace('<div class="item-card-footer">','<p class="equipment-source">'+esc(i.source_note)+'</p><div class="item-card-footer">');return html};
const detailsOldAll=renderAll;renderAll=function(){detailsOldAll();renderIdentityDetails();renderQuickSheetStrip();const panel=document.getElementById('quickSheetPanel');if(panel&&!panel.hidden&&!panel.contains(document.activeElement))renderQuickSheetPanel(panel.dataset.mode)};
document.addEventListener('DOMContentLoaded',()=>{const skills=document.getElementById('skillsList')?.previousElementSibling;if(skills)skills.textContent='Competencias de la ficha anterior, editables según tu progreso.';const host=document.getElementById('battleDesk'),strip=document.createElement('div');strip.id='quickSheetStrip';const panel=document.createElement('section');panel.id='quickSheetPanel';panel.hidden=true;host.querySelector('.turn-strip').after(strip,panel);const ac=document.getElementById('acDisplay');ac.onclick=()=>{if(currentView!=='combat')switchTab('combat');toggleQuickSheet('armor')};ac.setAttribute('role','button');ac.setAttribute('tabindex','0');ac.setAttribute('aria-label','Ver armadura y desglose de CA');ac.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();ac.click()}};renderIdentityDetails();renderQuickSheetStrip()});
